import 'package:flutter/material.dart';import '../data/income_database.dart';import '../models/income_models.dart';
class HomePage extends StatelessWidget{const HomePage({super.key,required this.revision,required this.onOpenHistory});final int revision;final VoidCallback onOpenHistory;
 @override Widget build(BuildContext context){final year=DateTime.now().year;return FutureBuilder<List<IncomeRecord>>(key:ValueKey(revision),future:IncomeDatabase.instance.forYear(year),builder:(context,snapshot){final records=snapshot.data??const<IncomeRecord>[];final types=records.map((e)=>e.type).toSet().toList();final monthly=List.generate(12,(m)=>records.where((r)=>r.date.month==m+1).fold<int>(0,(s,r)=>s+r.amount));final maxValue=monthly.fold<int>(0,(a,b)=>a>b?a:b);return Padding(padding:const EdgeInsets.fromLTRB(20,18,20,10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(year.toString()+'년 나의 수입',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:6),Text(types.isEmpty?'아직 기록된 수입이 없어요.':types.length.toString()+'가지 수입원에서 수입이 들어오고 있어요.'),const SizedBox(height:8),Wrap(spacing:6,children:types.map((e)=>Chip(label:Text(e.label))).toList()),const SizedBox(height:12),Text(year.toString()+'년 수입 흐름',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Expanded(flex:3,child:Card(child:Padding(padding:const EdgeInsets.fromLTRB(10,16,10,8),child:Row(crossAxisAlignment:CrossAxisAlignment.end,children:List.generate(12,(i){final h=maxValue==0?0.04:(monthly[i]/maxValue).clamp(0.04,1.0);return Expanded(child:Column(mainAxisAlignment:MainAxisAlignment.end,children:[Expanded(child:Align(alignment:Alignment.bottomCenter,child:FractionallySizedBox(heightFactor:h,widthFactor:.58,child:DecoratedBox(decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer,borderRadius:BorderRadius.circular(5)))))),const SizedBox(height:4),Text((i+1).toString(),style:const TextStyle(fontSize:10))]));}))))),const SizedBox(height:12),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('최근 수입',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold)),TextButton(onPressed:onOpenHistory,child:const Text('더보기'))]),Expanded(flex:2,child:records.isEmpty?const Center(child:Text('+ 버튼으로 첫 수입을 기록해보세요.')):ListView(children:records.take(3).map((r)=>ListTile(dense:true,contentPadding:EdgeInsets.zero,title:Text((r.source??r.type.label)+' · '+r.type.label),subtitle:r.account==null?null:Text(r.account!),trailing:Text('₩'+r.amount.toString()))).toList()))]));});}}
